contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialMinSum, uint256 newMinSum, uint256 depositAmount) public {
        // restrict to admissible values
        vm.assume(initialMinSum != newMinSum);
        vm.assume(depositAmount > 0);

        // initialize the contract
        c.SetMinSum(initialMinSum);
        c.Initialized();

        // deploy a re-entrant attacker that calls SetMinSum during Collect
        ReentrantAttacker attacker = new ReentrantAttacker(c, newMinSum);
        vm.deal(address(attacker), depositAmount);

        // attacker deposits to have a balance, then collects to trigger reentrancy
        attacker.deposit{value: depositAmount}();

        // warp past unlock time (now + 0 is fine)
        vm.warp(block.timestamp + 1);

        attacker.collect();

        // After all calls, MinSum must remain the initialized value
        // The re-entrant attacker attempts to change it; reference C prevents this via the lock.
        assertEq(c.MinSum(), initialMinSum, "MinSum changed after initialization");
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public newMinSum;
    uint256 public collectAmount;
    bool public reentered;

    constructor(C _target, uint256 _newMinSum) {
        target = _target;
        newMinSum = _newMinSum;
    }

    function deposit() external payable {
        target.Put{value: msg.value}(0);
        collectAmount = msg.value;
    }

    function collect() external {
        // We need to call Collect; the victim contract will call back to this address.
        // To make the call succeed, we need a receive function, but we want to reenter.
        // Use a low-level call to trigger fallback/receive on ourselves? No, we just call target.Collect.
        // The target will attempt to send Ether back to us (msg.sender is this contract).
        // During that send, our receive function is invoked, and we call target.SetMinSum(newMinSum).
        // That's the reentrancy vector.
        reentered = false;
        target.Collect(collectAmount);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-enter: try to change MinSum
            target.SetMinSum(newMinSum);
        }
    }
}

